import * as React from "react";
import { cn } from "@/lib/utils";

// =============================================================================
// TYPES
// =============================================================================

export type Kind = "display" | "headline" | "title" | "label" | "body";
export type Variant = "large" | "medium" | "small";
export type Color =
  | "primary"
  | "secondary"
  | "muted"
  | "placeholder"
  | "link"
  | "inverted"
  | "error"
  | "success";
export type Align = "left" | "center" | "right";

type Key = `${Kind}-${Variant}`;

// =============================================================================
// MAPPINGS
// =============================================================================

/**
 * Maps kind-variant combinations to semantic HTML tags
 */
const mapTagName: { [key in Key]: keyof React.JSX.IntrinsicElements } = {
  "display-large": "h4",
  "display-medium": "h4",
  "display-small": "h4",
  "headline-large": "h1",
  "headline-medium": "h2",
  "headline-small": "h3",
  "title-large": "h5",
  "title-medium": "h5",
  "title-small": "h5",
  "label-large": "label",
  "label-medium": "label",
  "label-small": "label",
  "body-large": "span",
  "body-medium": "span",
  "body-small": "span",
};

/**
 * Maps kind-variant combinations to Tailwind typography classes
 */
const mapClassName: { [key in Key]: string } = {
  "display-large": "text-[57px] leading-[64px] font-normal",
  "display-medium": "text-[45px] leading-[52px] font-normal",
  "display-small": "text-[36px] leading-[44px] font-normal",
  "headline-large": "text-[32px] leading-[40px] font-semibold",
  "headline-medium": "text-[28px] leading-[36px] font-semibold",
  "headline-small": "text-[24px] leading-[32px] font-semibold",
  "title-large": "text-lg leading-[22px] font-semibold",
  "title-medium": "text-base leading-5 font-semibold",
  "title-small": "text-sm leading-[18px] font-semibold",
  "label-large": "text-sm leading-5 font-semibold",
  "label-medium": "text-xs leading-4 font-semibold",
  "label-small": "text-[10px] leading-[14px] font-semibold",
  "body-large": "text-base leading-5 font-normal",
  "body-medium": "text-sm leading-[18px] font-normal",
  "body-small": "text-xs leading-4 font-normal",
};

/**
 * Maps color variants to Tailwind text color classes
 */
const mapColorClassName: { [key in Color]: string } = {
  primary: "text-semantic-text-primary",
  secondary: "text-semantic-text-secondary",
  muted: "text-semantic-text-muted",
  placeholder: "tw-text-semantic-text-placeholder",
  link: "text-semantic-text-link",
  inverted: "text-semantic-text-inverted",
  error: "text-semantic-error-primary",
  success: "text-semantic-success-primary",
};

/**
 * Maps alignment to Tailwind text alignment classes
 */
const mapAlignClassName: { [key in Align]: string } = {
  left: "text-left",
  center: "text-center",
  right: "text-right",
};

// =============================================================================
// COMPONENT
// =============================================================================

/**
 * Typography component props
 */
export interface TypographyProps extends React.HTMLAttributes<HTMLElement> {
  /** Text content */
  children: React.ReactNode;
  /** Typography kind - determines base styling and semantic tag */
  kind?: Kind;
  /** Size variant */
  variant?: Variant;
  /** Text color */
  color?: Color;
  /** Text alignment */
  align?: Align;
  /** Enable text truncation with ellipsis */
  truncate?: boolean;
  /** Override the default HTML tag */
  tag?: keyof React.JSX.IntrinsicElements;
  /** For label elements - associates with form input */
  htmlFor?: string;
}

/**
 * A semantic typography component for consistent text styling.
 *
 * @example
 * ```tsx
 * // Basic usage
 * <Typography kind="headline" variant="large">Page Title</Typography>
 *
 * // With color
 * <Typography kind="body" color="muted">Helper text</Typography>
 *
 * // Form label
 * <Typography kind="label" variant="medium" htmlFor="email">Email</Typography>
 *
 * // Truncated text
 * <Typography truncate>Very long text that will be truncated...</Typography>
 * ```
 */
const Typography = React.forwardRef(
  (
    {
      children,
      kind = "body",
      variant = "medium",
      color,
      align,
      truncate = false,
      className,
      tag,
      htmlFor,
      ...props
    }: TypographyProps,
    ref: React.Ref<HTMLElement>
  ) => {
    const key: Key = `${kind}-${variant}`;
    const Tag = (tag || mapTagName[key]) as React.ElementType;

    const classes = cn(
      "m-0", // Reset margin
      mapClassName[key],
      color && mapColorClassName[color],
      align && mapAlignClassName[align],
      truncate && "truncate",
      className
    );

    const tagName = tag || mapTagName[key];

    return (
      <Tag
        ref={ref}
        className={classes}
        htmlFor={tagName === "label" ? htmlFor : undefined}
        {...props}
      >
        {children}
      </Tag>
    );
  }
);
Typography.displayName = "Typography";

export {
  Typography,
  mapTagName,
  mapClassName,
  mapColorClassName,
  mapAlignClassName,
};

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Check } from "lucide-react";

import { cn } from "@/lib/utils";

const blockedNumberKeys = new Set(["e", "E"]);
const decimalSeparatorKeys = new Set([".", ","]);

/**
 * Input variants for different visual states
 */
const inputVariants = cva(
  "h-[42px] w-full rounded bg-semantic-bg-primary px-4 py-2 text-base text-semantic-text-primary outline-none transition-all file:border-0 file:bg-transparent file:text-base file:font-medium file:text-semantic-text-primary placeholder:text-semantic-text-placeholder disabled:cursor-not-allowed disabled:opacity-50 disabled:bg-[var(--color-neutral-50)]",
  {
    variants: {
      state: {
        default:
          "border border-solid border-semantic-border-input focus:outline-none focus:border-semantic-border-input-focus focus:shadow-[0_0_0_1px_rgba(43,188,202,0.15)]",
        error:
          "border border-solid border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus:outline-none focus:border-semantic-error-primary focus:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]",
      },
    },
    defaultVariants: {
      state: "default",
    },
  }
);

/**
 * A flexible input component for text entry with state variants.
 *
 * @example
 * ```tsx
 * <Input placeholder="Enter your email" />
 * <Input state="error" placeholder="Invalid input" />
 * <Input showCheckIcon placeholder="Enter amount" />
 * ```
 */
export interface InputProps
  extends
    Omit<React.ComponentProps<"input">, "size">,
    VariantProps<typeof inputVariants> {
  /** Shows a check icon on the right side when the input is focused */
  showCheckIcon?: boolean;
  /**
   * When `type="number"`, hide native stepper arrows (WebKit/Firefox).
   * Default `true` — matches existing app-wide number styling.
   * Set `false` to show native increment/decrement controls (e.g. delay fields).
   */
  hideNumberSpinners?: boolean;
  /**
   * When `type="number"`, prevent scientific notation characters (`e`/`E`).
   * Default `true` so amount-like fields cannot accept exponent values such as `2e22`.
   */
  preventNumberExponent?: boolean;
  /**
   * When `type="number"`, whether decimal separators (`.` / `,`) are allowed.
   * Default `true`. Set `false` for whole-number-only fields; uses `inputMode="numeric"` on supported agents.
   */
  decimal?: boolean;
  /**
   * Same as `decimal` for whole-number-only fields. If both are set, this wins.
   */
  allowDecimal?: boolean;
}

const Input = React.forwardRef(
  (
    {
      className,
      state,
      type,
      showCheckIcon,
      hideNumberSpinners = true,
      preventNumberExponent = true,
      decimal = true,
      allowDecimal,
      onFocus,
      onBlur,
      onWheel,
      onKeyDown,
      onPaste,
      onChange,
      step,
      ...props
    }: InputProps,
    ref: React.Ref<HTMLInputElement>
  ) => {
    const [isFocused, setIsFocused] = React.useState(false);
    const decimalAllowed = allowDecimal ?? decimal;
    const shouldPreventNumberExponent =
      type === "number" && preventNumberExponent;
    const shouldBlockDecimals =
      type === "number" && !decimalAllowed;

    const inputEl = (
      <input
        type={type}
        className={cn(
          inputVariants({ state }),
          className,
          state === "error" &&
            "border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus:border-semantic-error-primary focus:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]",
          showCheckIcon && "pr-9",
          type === "number" &&
            hideNumberSpinners &&
            "[appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
        )}
        ref={ref}
        inputMode={
          type === "number"
            ? decimalAllowed
              ? "decimal"
              : "numeric"
            : undefined
        }
        step={
          type === "number" && !decimalAllowed ? (step ?? 1) : step
        }
        onFocus={(e) => {
          setIsFocused(true);
          onFocus?.(e);
        }}
        onBlur={(e) => {
          setIsFocused(false);
          onBlur?.(e);
        }}
        onWheel={
          type === "number"
            ? (e) => {
                e.currentTarget.blur();
                onWheel?.(e);
              }
            : onWheel
        }
        onKeyDown={(e) => {
          if (shouldPreventNumberExponent && blockedNumberKeys.has(e.key)) {
            e.preventDefault();
          }
          if (
            shouldBlockDecimals &&
            decimalSeparatorKeys.has(e.key)
          ) {
            e.preventDefault();
          }
          onKeyDown?.(e);
        }}
        onPaste={(e) => {
          const text = e.clipboardData.getData("text");
          if (shouldPreventNumberExponent && /[eE]/.test(text)) {
            e.preventDefault();
          }
          if (shouldBlockDecimals && /[.,]/.test(text)) {
            e.preventDefault();
          }
          onPaste?.(e);
        }}
        onChange={(e) => {
          if (shouldPreventNumberExponent && /[eE]/.test(e.target.value)) {
            return;
          }
          if (shouldBlockDecimals && /[.,]/.test(e.target.value)) {
            return;
          }
          onChange?.(e);
        }}
        {...props}
      />
    );

    if (!showCheckIcon) return inputEl;

    return (
      <div className="relative w-full">
        {inputEl}
        {isFocused && (
          <Check className="absolute right-3 top-1/2 -translate-y-1/2 size-4 text-semantic-brand pointer-events-none" />
        )}
      </div>
    );
  }
);
Input.displayName = "Input";

export { Input, inputVariants };

