 */
export interface TextareaProps
  extends Omit<React.ComponentProps<"textarea">, "size">,
    VariantProps<typeof textareaVariants> {
  /** Size of the textarea — `default` or `sm` (compact) */
  size?: "default" | "sm";
  /** Label text displayed above the textarea */
  label?: string;
  /** Shows red asterisk next to label when true */
  required?: boolean;
  /** Helper text displayed below the textarea */
  helperText?: string;
  /** Error message — shows error state with red styling */
  error?: string;
  /**
   * When true and `error` is set, shows a leading error icon with the message (field-level validation pattern).
   */
  errorIcon?: boolean;
  /** Shows character count when maxLength is set */
  showCount?: boolean;
  /**
   * When set, the counter shows this number instead of the default normalized length
   * (see `countNonWhitespaceChars` in this file).
   * Does not change native `maxLength` or stored value — display only.
   */
  displayCharCount?: number;
  /**
   * When true (default), `maxLength` is applied to the native textarea (hard limit).
   * When false, the limit is only used for `showCount` / styling — pair with `error` or parent validation for soft limits.
   */
  enforceMaxLength?: boolean;
  /** Controls CSS resize behavior. Defaults to "none" */
  resize?: "none" | "vertical" | "horizontal" | "both";
  /** Additional class for the wrapper container */
  wrapperClassName?: string;
  /** Additional class for the label */
  labelClassName?: string;
}

const Textarea = React.forwardRef(
  (
    {
      className,
      wrapperClassName,
      labelClassName,
      state,
      size,
      label,
      required,
      helperText,
      error,
      errorIcon = false,
      showCount,
      displayCharCount,
      enforceMaxLength = true,
      resize = "none",
      maxLength,
      rows = 4,
      value,
      defaultValue,
      onChange,
      disabled,
      id,
      ...props
    }: TextareaProps,
    ref: React.ForwardedRef<HTMLTextAreaElement>
  ) => {
    // Internal state for character count in uncontrolled mode (normalized)
    const [internalValue, setInternalValue] = React.useState(() =>
      normalizeTextareaSpaces(String(defaultValue ?? ""))
    );

    // Determine if controlled
    const isControlled = value !== undefined;
    const currentValue = isControlled
      ? normalizeTextareaSpaces(String(value ?? ""))
      : internalValue;

    // Derive state from props
    const derivedState = error ? "error" : (state ?? "default");

    // Handle change for both controlled and uncontrolled — collapse duplicate spaces
    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const normalized = normalizeTextareaSpaces(e.target.value);
      if (!isControlled) {
        setInternalValue(normalized);
      }
      if (!onChange) return;
      if (normalized === e.target.value) {
        onChange(e);
        return;
      }
      onChange({
        ...e,
        target: { ...e.target, value: normalized },
        currentTarget: { ...e.currentTarget, value: normalized },
      } as React.ChangeEvent<HTMLTextAreaElement>);
    };

    const charCount =
      displayCharCount !== undefined
        ? displayCharCount
        : countNonWhitespaceChars(String(currentValue));

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const textareaId = id || generatedId;
    const helperId = `${textareaId}-helper`;
    const errorId = `${textareaId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Resize class map
    const resizeClasses: Record<string, string> = {
      none: "resize-none",
      vertical: "resize-y",
      horizontal: "resize-x",
      both: "resize",
    };

    return (
      <div className={cn("flex flex-col gap-1", wrapperClassName)}>
        {/* Label */}
        {label && (
          <label
            htmlFor={textareaId}
            className={cn(
              "text-sm font-medium text-semantic-text-muted",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Textarea */}
        <textarea
          ref={ref}
          id={textareaId}
          rows={rows}
          className={cn(
            textareaVariants({ state: derivedState, size }),
            className,
            derivedState === "error" &&
              "border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus:border-semantic-error-primary focus:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]",
            resizeClasses[resize]
          )}
          disabled={disabled}
          required={required}
          maxLength={
            enforceMaxLength !== false ? maxLength : undefined
          }
          value={currentValue}
          onChange={handleChange}
          aria-invalid={!!error}
          aria-describedby={ariaDescribedBy}
          {...props}
        />

        {/* Helper text / Error message / Character count */}
        {(error || helperText || (showCount && maxLength)) && (
          <div className="flex justify-between items-start gap-2">
            {error ? (
              errorIcon ? (
                <div
                  id={errorId}
                  role="alert"
                  className="flex items-center gap-1.5 min-w-0"
                >
                  <CircleAlert
                    className="size-3.5 shrink-0 text-semantic-error-primary"
                    aria-hidden
                  />
                  <span className="text-sm text-semantic-error-primary">
                    {error}
                  </span>
                </div>
              ) : (
                <span
                  id={errorId}
                  className="text-sm text-semantic-error-primary"
                >
                  {error}
                </span>
              )
            ) : helperText ? (
              <span id={helperId} className="text-sm text-semantic-text-muted">
                {helperText}
              </span>
            ) : (
              <span />
            )}
            {showCount && maxLength && (
              <span
                className={cn(
                  "text-sm",
                  charCount > maxLength
                    ? "text-semantic-error-primary"
                    : "text-semantic-text-muted"
                )}
              >
                {charCount}/{maxLength}
              </span>
            )}
          </div>
        )}
      </div>
    );
  }
);
Textarea.displayName = "Textarea";

export { Textarea, textareaVariants };

import * as React from "react";
import { Copy, Check, Eye, EyeOff } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ReadableFieldProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /** Label text displayed above the field */
  label: string;
  /** Value to display and copy */
  value: string;
  /** Helper text displayed below the field */
  helperText?: string;
  /** When true, masks the value with dots and shows eye toggle */
  secret?: boolean;
  /** Header action (e.g., "Regenerate" link) */
  headerAction?: {
    label: string;
    onClick: () => void;
    /** When true, button is shown but non-interactive */
    disabled?: boolean;
    /** Tooltip text shown on hover when disabled */
    disabledTooltip?: string;
  };
  /** Callback when value is copied */
  onValueCopy?: (value: string) => void;
  /** Additional class for the input container */
  inputClassName?: string;
}

/**
 * ReadableField displays a read-only value with copy-to-clipboard functionality.
 * Supports secret mode for sensitive data like API keys and passwords.
 *
 * @example
 * ```tsx
 * // Simple readable field
 * <ReadableField
 *   label="Base URL"
 *   value="https://api.myoperator.co/v3/voice/gateway"
 * />
 *
 * // Secret field with regenerate action
 * <ReadableField
 *   label="Authentication"
 *   value="sk_live_abc123xyz"
 *   secret
 *   helperText="Used for client-side integrations."
 *   headerAction={{
 *     label: "Regenerate",
 *     onClick: () => console.log("Regenerate clicked"),
 *   }}
 * />
 * ```
 */
export const ReadableField = React.forwardRef(
  (
    {
      label,
      value,
      helperText,
      secret = false,
      headerAction,
      onValueCopy,
      className,
      inputClassName,
      ...props
    }: ReadableFieldProps,
    ref: React.Ref<HTMLDivElement>
  ) => {
    const [copied, setCopied] = React.useState(false);
    const [isVisible, setIsVisible] = React.useState(!secret);
    const timeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

    // Sync visibility state when secret prop changes
    React.useEffect(() => {
      setIsVisible(!secret);
    }, [secret]);

    // Cleanup timeout on unmount to prevent memory leaks
    React.useEffect(() => {
      return () => {
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
      };
    }, []);

    const handleCopy = async () => {
      try {
        await navigator.clipboard.writeText(value);
        setCopied(true);
        onValueCopy?.(value);

        // Clear existing timeout before setting new one
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
        timeoutRef.current = setTimeout(() => setCopied(false), 2000);
      } catch {
        // Clipboard API may fail in insecure contexts
      }
    };

    const toggleVisibility = () => {
      setIsVisible((prev) => !prev);
    };

    // Display masked or actual value
    const displayValue = secret && !isVisible ? "••••••••••••••••••••" : value;

    return (
      <div
        ref={ref}
        className={cn("flex flex-col gap-1", className)}
        {...props}
      >
        {/* Header Row: Label + Optional Action */}
        <div className="flex items-start justify-between">
          <span className="text-sm text-semantic-text-muted tracking-[0.035px]">
            {label}
          </span>
          {headerAction && (
            headerAction.disabled ? (
              <span className="relative group/regen-action">
                <button
                  type="button"
                  disabled
                  className="text-sm font-semibold text-semantic-text-muted tracking-[0.014px] opacity-50 cursor-not-allowed rounded"
                >
                  {headerAction.label}
                </button>
                {headerAction.disabledTooltip && (
                  <span className="pointer-events-none absolute bottom-full right-0 mb-2 whitespace-nowrap rounded bg-semantic-primary px-2 py-1 text-xs text-semantic-text-inverted opacity-0 transition-opacity group-hover/regen-action:opacity-100 z-10">
                    {headerAction.disabledTooltip}
                    <span className="absolute top-full right-2 border-4 border-solid border-transparent border-t-semantic-primary" />
                  </span>
                )}
              </span>
            ) : (
              <button
                type="button"
                onClick={headerAction.onClick}
                className="text-sm font-semibold text-semantic-text-muted tracking-[0.014px] hover:text-semantic-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-semantic-text-primary rounded transition-colors"
              >
                {headerAction.label}
              </button>
            )
          )}
        </div>

        {/* Input Container */}
        <div
          className={cn(
            "flex h-11 items-center justify-between rounded border border-solid border-semantic-border-layout bg-semantic-bg-ui pl-4 pr-2.5 py-2.5",
            inputClassName
          )}
        >
          {/* Value Display */}
          <span className="text-base text-semantic-text-primary tracking-[0.08px] truncate">
            {displayValue}
          </span>

          {/* Action Icons */}
          <div className="flex items-center gap-4 shrink-0">
            {/* Eye Toggle (only for secret mode) */}
            {secret && (
              <button
                type="button"
                onClick={toggleVisibility}
                className="text-semantic-text-muted hover:text-semantic-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-semantic-text-primary rounded transition-colors"
                aria-label={isVisible ? "Hide value" : "Show value"}
              >
                {isVisible ? (
                  <EyeOff className="size-[18px]" />
                ) : (
                  <Eye className="size-[18px]" />
                )}
              </button>
            )}

            {/* Copy Button */}
            <button
              type="button"
              onClick={handleCopy}
              className={cn(
                "rounded transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-semantic-text-primary",
                copied
                  ? "text-semantic-success-primary"
                  : "text-semantic-text-muted hover:text-semantic-text-primary"
              )}
              aria-label={copied ? "Copied" : "Copy to clipboard"}
            >
              {copied ? (
                <Check className="size-[18px]" />
              ) : (
                <Copy className="size-[18px]" />
              )}
            </button>
          </div>
        </div>

        {/* Helper Text */}
        {helperText && (
          <p className="m-0 text-sm text-semantic-text-muted tracking-[0.035px]">
            {helperText}
          </p>
        )}
      </div>
    );
  }
);

ReadableField.displayName = "ReadableField";

import * as React from "react";
import { Loader2, Search } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "./select";

export interface SelectOption {
  /** The value of the option */
  value: string;
  /** The display label of the option */
  label: string;
  /** Whether the option is disabled */
  disabled?: boolean;
  /** Group name for grouping options */
  group?: string;
}

export interface SelectFieldProps {
  /** Label text displayed above the select */
  label?: string;
  /** Shows red asterisk next to label when true */
  required?: boolean;
  /** Helper text displayed below the select */
  helperText?: string;
  /** Error message - shows error state with red styling */
  error?: string;
  /** Disabled state */
  disabled?: boolean;
  /** Loading state with spinner */
  loading?: boolean;
  /** Placeholder text when no value selected */
  placeholder?: string;
  /** Currently selected value (controlled) */
  value?: string;
  /** Default value (uncontrolled) */
  defaultValue?: string;
  /** Callback when value changes */
  onValueChange?: (value: string) => void;
  /** Callback when an option is selected, provides the full option object */
  onSelect?: (option: SelectOption) => void;
  /**
   * Intercept a value change before it commits. Return `false` to prevent
   * `onValueChange` from firing (only `onSelect` will fire). Useful for
   * "action" items like "Add custom date" that should open a modal instead
   * of committing a value. Requires controlled mode (`value` prop) to
   * visually revert the selection.
   */
  interceptValue?: (value: string) => boolean;
  /** Options to display */
  options: SelectOption[];
  /** Enable search/filter functionality */
  searchable?: boolean;
  /** Search placeholder text */
  searchPlaceholder?: string;
  /**
   * Controlled search value. When provided, internal search state is
   * ignored and the consumer owns the value — typically used to drive
   * server-side filtering against a paginated API. The client-side
   * `option.label` filter is also skipped, since the consumer is expected
   * to have already filtered the options upstream.
   *
   * Pair with `onSearchChange`. Leave both undefined for the default
   * uncontrolled, client-side filtering behavior.
   */
  searchValue?: string;
  /**
   * Fires on every keystroke in the search input. Also fires with `""`
   * when the dropdown closes (so consumers can reset their query state).
   */
  onSearchChange?: (value: string) => void;
  /** Additional class for wrapper */
  wrapperClassName?: string;
  /** Additional class for trigger */
  triggerClassName?: string;
  /** Additional class for label */
  labelClassName?: string;
  /** ID for the select */
  id?: string;
  /** Name attribute for form submission */
  name?: string;
  /**
   * Fires when the user scrolls to the bottom of the open dropdown.
   * Use this to load the next page from the server. The callback is
   * forwarded to SelectContent's `onViewportScrollEnd` (debounced by
   * the native `scrollend` event), so it won't fire while a scroll is
   * still in progress.
   *
   * No virtualization is applied — all loaded items render to the DOM.
   * For >2k items consumers may notice some lag; virtualization is a
   * separate ticket if it becomes a real-world problem.
   */
  onScrollEnd?: () => void;
  /**
   * When true, renders a small "Loading more…" row at the bottom of
   * the options list. Set this to true while your API call is in flight
   * so the user knows more items are on the way.
   */
  loadingMore?: boolean;
  /**
   * When false, prevents `onScrollEnd` from firing further and renders
   * an "End of list" footer row. Default true (keep firing).
   */
  hasMore?: boolean;
}

/**
 * A comprehensive select field component with label, icons, validation states, and more.
 *
 * @example
 * ```tsx
 * <SelectField
 *   label="Authentication"
 *   placeholder="Select authentication method"
 *   options={[
 *     { value: 'none', label: 'None' },
 *     { value: 'basic', label: 'Basic Auth' },
 *     { value: 'bearer', label: 'Bearer Token' },
 *   ]}
 *   required
 * />
 * ```
 *
 * @example Lazy-load on scroll
 * ```tsx
 * const [items, setItems] = useState<SelectOption[]>([]);
 * const [loadingMore, setLoadingMore] = useState(false);
 * const [hasMore, setHasMore] = useState(true);
 * const page = useRef(0);
 *
 * const loadNext = async () => {
 *   if (loadingMore || !hasMore) return;
 *   setLoadingMore(true);
 *   const { results, isLast } = await api.fetchTemplates(page.current);
 *   setItems(prev => [...prev, ...results]);
 *   setHasMore(!isLast);
 *   page.current += 1;
 *   setLoadingMore(false);
 * };
 *
 * useEffect(() => { loadNext(); }, []);
 *
 * <SelectField
 *   label="Template"
 *   options={items}
 *   onScrollEnd={loadNext}
 *   loadingMore={loadingMore}
 *   hasMore={hasMore}
 * />
 * ```
 */
const SelectField = React.forwardRef(
  (
    {
      label,
      required,
      helperText,
      error,
      disabled,
      loading,
      placeholder = "Select an option",
      value,
      defaultValue,
      onValueChange,
      onSelect,
      interceptValue,
      options,
      searchable,
      searchPlaceholder = "Search...",
      searchValue,
      onSearchChange,
      wrapperClassName,
      triggerClassName,
      labelClassName,
      id,
      name,
      onScrollEnd,
      loadingMore,
      hasMore,
    }: SelectFieldProps,
    ref: React.Ref<HTMLButtonElement>
  ) => {
    // Internal state for uncontrolled mode. When `searchValue` is provided,
    // the consumer owns the value and this state is unused.
    const [searchQuery, setSearchQuery] = React.useState("");
    const isSearchControlled = searchValue !== undefined;
    const effectiveSearchQuery = isSearchControlled ? searchValue : searchQuery;

    // Combined value change handler that also fires onSelect with full option object.
    // When interceptValue returns false, onValueChange is skipped (only onSelect fires).
    const handleValueChange = React.useCallback(
      (newValue: string) => {
        const intercepted = interceptValue?.(newValue) === false;

        if (!intercepted) {
          onValueChange?.(newValue);
        }

        if (onSelect) {
          const option = options.find((o) => o.value === newValue);
          if (option) {
            onSelect(option);
          }
        }
      },
      [onValueChange, onSelect, interceptValue, options]
    );

    // Support re-selection: fire onSelect when clicking the already-selected
    // item. Radix only fires onValueChange for *new* values, so without this
    // clicking an action item like "Add custom date" a second time would be a
    // no-op.
    const handleItemClick = React.useCallback(
      (option: SelectOption) => {
        if (option.value === value) {
          handleValueChange(option.value);
        }
      },
      [value, handleValueChange]
    );

    // Derive state from props
    const derivedState = error ? "error" : "default";

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const selectId = id || generatedId;
    const helperId = `${selectId}-helper`;
    const errorId = `${selectId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Group options by group property
    const groupedOptions = React.useMemo(() => {
      const groups: Record<string, SelectOption[]> = {};
      const ungrouped: SelectOption[] = [];

      options.forEach((option) => {
        // Client-side filter only in uncontrolled mode. In controlled mode
        // the consumer has already filtered server-side; re-filtering here
        // would mask items their API returned.
        if (
          searchable &&
          !isSearchControlled &&
          searchQuery &&
          !option.label.toLowerCase().includes(searchQuery.toLowerCase())
        ) {
          return;
        }

        if (option.group) {
          if (!groups[option.group]) {
            groups[option.group] = [];
          }
          groups[option.group].push(option);
        } else {
          ungrouped.push(option);
        }
      });

      return { groups, ungrouped };
    }, [options, searchable, isSearchControlled, searchQuery]);

    const hasGroups = Object.keys(groupedOptions.groups).length > 0;

    // Count rendered options for the "End of list" footer (only show when at least one is visible).
    const totalRendered =
      groupedOptions.ungrouped.length +
      Object.values(groupedOptions.groups).reduce(
        (sum, items) => sum + items.length,
        0
      );
    const showEndOfList = hasMore === false && totalRendered > 0 && !loadingMore;

    // Handle search input change
    const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const next = e.target.value;
      if (!isSearchControlled) {
        setSearchQuery(next);
      }
      onSearchChange?.(next);
    };

    // Reset search when dropdown closes. In controlled mode we notify the
    // consumer so they can reset their state; in uncontrolled mode we clear
    // our own state directly.
    const handleOpenChange = (open: boolean) => {
      if (!open) {
        if (isSearchControlled) {
          onSearchChange?.("");
        } else {
          setSearchQuery("");
        }
      }
    };

    return (
      <div className={cn("flex flex-col gap-1", wrapperClassName)}>
        {/* Label */}
        {label && (
          <label
            htmlFor={selectId}
            className={cn(
              "text-sm font-medium text-semantic-text-muted",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Select */}
        <Select
          value={value}
          defaultValue={defaultValue}
          onValueChange={handleValueChange}
          disabled={disabled || loading}
          name={name}
          onOpenChange={handleOpenChange}
        >
          <SelectTrigger
            ref={ref}
            id={selectId}
            state={derivedState}
            className={cn(loading && "pr-10", triggerClassName)}
            aria-invalid={!!error}
            aria-describedby={ariaDescribedBy}
          >
            <SelectValue placeholder={placeholder} />
            {loading && (
              <Loader2 className="absolute right-8 size-4 animate-spin text-semantic-text-muted" />
            )}
          </SelectTrigger>
          <SelectContent
            onViewportScrollEnd={hasMore !== false ? onScrollEnd : undefined}
          >
            {/* Search input */}
            {searchable && (
              <div className="flex items-center gap-2 px-3 pb-1.5 border-b border-solid border-semantic-border-layout">
                <Search className="size-4 text-semantic-text-muted shrink-0" />
                <input
                  type="text"
                  placeholder={searchPlaceholder}
                  value={effectiveSearchQuery}
                  onChange={handleSearchChange}
                  className="w-full h-8 text-sm bg-transparent placeholder:text-semantic-text-muted focus:outline-none"
                  // Prevent closing dropdown when clicking input
                  onClick={(e) => e.stopPropagation()}
                  onKeyDown={(e) => e.stopPropagation()}
                />
              </div>
            )}

            {/* Ungrouped options */}
            {groupedOptions.ungrouped.map((option) => (
              <SelectItem
                key={option.value}
                value={option.value}
                disabled={option.disabled}
                onPointerUp={() => handleItemClick(option)}
              >
                {option.label}
              </SelectItem>
            ))}

            {/* Grouped options */}
            {hasGroups &&
              Object.entries(groupedOptions.groups).map(
                ([groupName, groupOptions]) => (
                  <SelectGroup key={groupName}>
                    <SelectLabel>{groupName}</SelectLabel>
                    {groupOptions.map((option) => (
                      <SelectItem
                        key={option.value}
                        value={option.value}
                        disabled={option.disabled}
                        onPointerUp={() => handleItemClick(option)}
                      >
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                )
              )}

            {/* No results message */}
            {searchable &&
              effectiveSearchQuery &&
              groupedOptions.ungrouped.length === 0 &&
              Object.keys(groupedOptions.groups).length === 0 && (
                <div className="py-6 text-center text-sm text-semantic-text-muted">
                  No results found
                </div>
              )}

            {/* Loading-more row (lazy-load) */}
            {loadingMore && (
              <div
                role="status"
                aria-live="polite"
                className="flex items-center justify-center gap-2 py-2 text-sm text-semantic-text-muted"
              >
                <Loader2 className="size-3.5 animate-spin" aria-hidden="true" />
                <span>Loading more…</span>
              </div>
            )}

            {/* End-of-list footer (lazy-load) */}
            {showEndOfList && (
              <div
                role="status"
                className="py-2 text-center text-xs text-semantic-text-muted"
              >
                End of list
              </div>
            )}
          </SelectContent>
        </Select>

        {/* Helper text / Error message */}
        {(error || helperText) && (
          <div className="flex justify-between items-start gap-2">
            {error ? (
              <span
                id={errorId}
                className="text-xs text-semantic-error-primary"
              >
                {error}
              </span>
            ) : helperText ? (
              <span id={helperId} className="text-xs text-semantic-text-muted">
                {helperText}
              </span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);
SelectField.displayName = "SelectField";

export { SelectField };

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Check, ChevronDown, CircleAlert, Loader2, X } from "lucide-react";

import { cn } from "@/lib/utils";
import { Checkbox } from "./checkbox";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "./tooltip";

/**
 * Single selectable row (similar to legacy OptionType — different name).
 * Selection state is driven by `value` / `onValueChange`, not by a prop.
 */
export interface MultiSelectChoice {
  value: string;
  label: string;
  /** Secondary line (e.g. “Assigned to …”) — alias of `secondaryText` on `MultiSelectOption` */
  caption?: string;
  /** Disabled row — alias of `disabled` */
  isDisabled?: boolean;
  /** Tooltip on disabled row — alias of `disabledTooltip` */
  overlayMsg?: string;
  isDeleted?: boolean;
  isLast?: boolean;
}

/**
 * Grouped options (similar to legacy GroupBase — different name).
 */
export interface MultiSelectGroupedSection<
  T extends MultiSelectChoice = MultiSelectChoice,
> {
  readonly label?: string;
  readonly options: readonly T[];
}

/** Flat list or grouped sections */
export type MultiSelectOptionInput =
  | MultiSelectOption[]
  | readonly MultiSelectGroupedSection[];

/**
 * Normalized option: supports both `caption` / `isDisabled` / `overlayMsg` and
 * `secondaryText` / `disabled` / `disabledTooltip`.
 */
export interface MultiSelectOption extends MultiSelectChoice {
  secondaryText?: string;
  disabled?: boolean;
  disabledTooltip?: string;
  group?: string;
}

/**
 * Use when typing **object literals** for fixtures, stories, or tests so TypeScript applies
 * [excess property checking](https://www.typescriptlang.org/docs/handbook/2/objects.html#excess-property-checks)
 * (catches typos like `captoin` and mistaken duplicate keys).
 *
 * This omits `secondaryText`; use `caption` for the secondary line — runtime code still accepts
 * both via {@link normalizeMultiSelectOption}. Widen to {@link MultiSelectOption} where a
 * consumer expects both aliases.
 */
export type MultiSelectOptionAuthoring = Omit<MultiSelectOption, "secondaryText">;

function isGroupedSections(
  input: MultiSelectOptionInput
): input is readonly MultiSelectGroupedSection[] {
  if (!Array.isArray(input) || input.length === 0) return false;
  return input.every(
    (item) =>
      item !== null &&
      typeof item === "object" &&
      "options" in item &&
      Array.isArray((item as MultiSelectGroupedSection).options)
  );
}

export function normalizeMultiSelectOption(
  o: MultiSelectOption | MultiSelectChoice
): MultiSelectOption {
  const merged = { ...(o as MultiSelectOption) };
  merged.disabled = merged.disabled ?? merged.isDisabled ?? false;
  merged.secondaryText = merged.secondaryText ?? merged.caption;
  merged.disabledTooltip = merged.disabledTooltip ?? merged.overlayMsg;
  return merged;
}

export function flattenMultiSelectOptions(
  input: MultiSelectOptionInput
): MultiSelectOption[] {
  if (!input?.length) return [];
  if (isGroupedSections(input)) {
    const out: MultiSelectOption[] = [];
    for (const section of input) {
      const groupLabel = section.label ?? "";
      for (const raw of section.options) {
        const n = normalizeMultiSelectOption(raw as MultiSelectOption);
        out.push({
          ...n,
          group: n.group ?? groupLabel,
        });
      }
    }
    return out;
  }
  return (input as MultiSelectOption[]).map(normalizeMultiSelectOption);
}

/**
 * MultiSelect trigger variants matching TextField styling
 */
const multiSelectTriggerVariants = cva(
  "flex min-h-[42px] w-full items-center justify-between rounded bg-semantic-bg-primary px-4 py-2 text-base text-semantic-text-primary transition-all disabled:cursor-not-allowed disabled:opacity-50 disabled:bg-[var(--color-neutral-50)]",
  {
    variants: {
      state: {
        default:
          "border border-solid border-semantic-border-input focus:outline-none focus:border-semantic-border-input-focus/50 focus:shadow-[0_0_0_1px_rgba(43,188,202,0.15)]",
        error:
          "border border-solid border-semantic-error-primary/40 focus:outline-none focus:border-semantic-error-primary/60 focus:shadow-[0_0_0_1px_rgba(240,68,56,0.1)]",
      },
    },
    defaultVariants: {
      state: "default",
    },
  }
);

export interface MultiSelectProps extends VariantProps<
  typeof multiSelectTriggerVariants
> {
  /** Label text displayed above the select */
  label?: string;
  /** Shows red asterisk next to label when true */
  required?: boolean;
  /** Helper text displayed below the select */
  helperText?: string;
  /** Error message - shows error state with red styling */
  error?: string;
  /** Disabled state */
  disabled?: boolean;
  /** Loading state with spinner */
  loading?: boolean;
  /** Placeholder text when no value selected */
  placeholder?: string;
  /** Currently selected values (controlled) */
  value?: string[];
  /** Default values (uncontrolled) */
  defaultValue?: string[];
  /** Callback when values change */
  onValueChange?: (value: string[]) => void;
  /** Flat options or grouped sections (`MultiSelectGroupedSection[]`) */
  options: MultiSelectOptionInput;
  /**
   * When false (default), the list only closes on outside click (not Escape).
   * Set true to also close on Escape.
   */
  closeOnEscape?: boolean;
  /** Enable search/filter functionality */
  searchable?: boolean;
  /** Search placeholder text */
  searchPlaceholder?: string;
  /** Maximum selections allowed */
  maxSelections?: number;
  /**
   * When `maxSelections` is set, a footer shows the count (e.g. "3 / 5 selected").
   * Set to false to hide that footer while still enforcing the limit.
   * @default true
   */
  showSelectionFooter?: boolean;
  /** Additional class for wrapper */
  wrapperClassName?: string;
  /** Additional class for trigger */
  triggerClassName?: string;
  /** Additional class for label */
  labelClassName?: string;
  /** ID for the select */
  id?: string;
  /** Name attribute for form submission */
  name?: string;
  /**
   * simple: checkmark on the right (default).
   * detailed: checkbox + primary + optional secondary text (Figma / WhatsApp-style rows).
   */
  optionVariant?: "simple" | "detailed";
  /** When true, selected options appear first with a divider before the rest */
  separateSelectedWithDivider?: boolean;
  /** Show the clear-all control in the trigger (hidden in compact / Figma-style triggers) */
  showClearAll?: boolean;
  /** Vertical rule before the chevron (Figma-style trigger) */
  showSeparatorBeforeChevron?: boolean;
  /**
   * When provided, pins a "select all" checkbox row above the options that
   * selects or clears every enabled option at once (respecting
   * `maxSelections` when set). Shows an indeterminate checkbox state when
   * some, but not all, options are selected. The value is the pinned row's
   * label, e.g. "All lines".
   */
  selectAllLabel?: string;
  /**
   * When provided, the trigger shows this compact summary instead of a chip
   * per selected option once at least one option is selected (e.g. `(count)
   * => \`${count} lines selected\``). Hovering the summary reveals the full
   * list of selected labels via a tooltip. Leave unset to keep the default
   * per-item chips.
   */
  summaryLabel?: (count: number) => string;
}

/**
 * A multi-select component with tags, search, and validation states.
 *
 * @example
 * ```tsx
 * <MultiSelect
 *   label="Skills"
 *   placeholder="Select skills"
 *   options={[
 *     { value: 'react', label: 'React' },
 *     { value: 'vue', label: 'Vue' },
 *     { value: 'angular', label: 'Angular' },
 *   ]}
 *   onValueChange={(values) => console.log(values)}
 * />
 * ```
 */
const MultiSelect = React.forwardRef(
  (
    {
      label,
      required,
      helperText,
      error,
      disabled,
      loading,
      placeholder = "Select options",
      value,
      defaultValue = [],
      onValueChange,
      options,
      searchable,
      searchPlaceholder = "Search...",
      maxSelections,
      showSelectionFooter = true,
      wrapperClassName,
      triggerClassName,
      labelClassName,
      state,
      id,
      name,
      optionVariant = "simple",
      separateSelectedWithDivider = false,
      showClearAll = true,
      showSeparatorBeforeChevron = false,
      closeOnEscape = false,
      selectAllLabel,
      summaryLabel,
    }: MultiSelectProps,
    ref: React.Ref<HTMLButtonElement>
  ) => {
    // Internal state for selected values (uncontrolled mode)
    const [internalValue, setInternalValue] =
      React.useState<string[]>(defaultValue);
    // Dropdown open state
    const [isOpen, setIsOpen] = React.useState(false);
    // Search query
    const [searchQuery, setSearchQuery] = React.useState("");

    // Container ref for click outside detection
    const containerRef = React.useRef<HTMLDivElement>(null);

    const flatOptions = React.useMemo(
      () => flattenMultiSelectOptions(options),
      [options]
    );

    // Determine if controlled
    const isControlled = value !== undefined;
    const selectedValues = isControlled ? value : internalValue;

    // Derive state from props
    const derivedState = error ? "error" : (state ?? "default");

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const selectId = id || generatedId;
    const listboxId = `${selectId}-listbox`;
    const helperId = `${selectId}-helper`;
    const errorId = `${selectId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Filter options by search query
    const filteredOptions = React.useMemo(() => {
      if (!searchable || !searchQuery.trim()) return flatOptions;
      const q = searchQuery.toLowerCase();
      return flatOptions.filter((option) => {
        const secondary = option.secondaryText ?? "";
        return (
          option.label.toLowerCase().includes(q) ||
          secondary.toLowerCase().includes(q) ||
          (option.group?.toLowerCase().includes(q) ?? false)
        );
      });
    }, [flatOptions, searchable, searchQuery]);

    type DisplayItem =
      | { type: "option"; option: MultiSelectOption }
      | { type: "divider" }
      | { type: "header"; label: string };

    const hasGroupedOptions = flatOptions.some(
      (o) => o.group !== undefined && o.group !== ""
    );

    const displayItems = React.useMemo((): DisplayItem[] => {
      const filtered = filteredOptions;

      if (separateSelectedWithDivider) {
        const selected = filtered.filter((o) =>
          selectedValues.includes(o.value)
        );
        const unselected = filtered.filter(
          (o) => !selectedValues.includes(o.value)
        );
        const items: DisplayItem[] = selected.map((o) => ({
          type: "option",
          option: o,
        }));
        if (selected.length > 0 && unselected.length > 0) {
          items.push({ type: "divider" });
        }
        items.push(
          ...unselected.map((o) => ({ type: "option" as const, option: o }))
        );
        return items;
      }

      if (hasGroupedOptions) {
        const order: string[] = [];
        const byGroup = new Map<string, MultiSelectOption[]>();
        for (const o of filtered) {
          const g = o.group ?? "";
          if (!byGroup.has(g)) {
            byGroup.set(g, []);
            order.push(g);
          }
          byGroup.get(g)!.push(o);
        }
        const items: DisplayItem[] = [];
        for (const g of order) {
          if (g) {
            items.push({ type: "header", label: g });
          }
          for (const o of byGroup.get(g)!) {
            items.push({ type: "option", option: o });
          }
        }
        return items;
      }

      return filtered.map((o) => ({ type: "option" as const, option: o }));
    }, [
      filteredOptions,
      hasGroupedOptions,
      separateSelectedWithDivider,
      selectedValues,
    ]);

    // Get selected option labels
    const selectedLabels = React.useMemo(() => {
      return selectedValues
        .map((v) => flatOptions.find((o) => o.value === v)?.label)
        .filter(Boolean) as string[];
    }, [selectedValues, flatOptions]);

    // Handle toggle selection
    const toggleOption = (optionValue: string) => {
      const newValues = selectedValues.includes(optionValue)
        ? selectedValues.filter((v) => v !== optionValue)
        : maxSelections && selectedValues.length >= maxSelections
          ? selectedValues
          : [...selectedValues, optionValue];

      if (!isControlled) {
        setInternalValue(newValues);
      }
      onValueChange?.(newValues);
    };

    // Handle remove tag
    const removeValue = (valueToRemove: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const newValues = selectedValues.filter((v) => v !== valueToRemove);
      if (!isControlled) {
        setInternalValue(newValues);
      }
      onValueChange?.(newValues);
    };

    // Handle clear all
    const clearAll = (e: React.MouseEvent) => {
      e.stopPropagation();
      if (!isControlled) {
        setInternalValue([]);
      }
      onValueChange?.([]);
    };

    // Select-all: values eligible for select-all exclude disabled options
    const selectableValues = React.useMemo(
      () => flatOptions.filter((o) => !o.disabled).map((o) => o.value),
      [flatOptions]
    );
    const allSelected =
      selectableValues.length > 0 &&
      selectableValues.every((v) => selectedValues.includes(v));
    const someSelected = selectedValues.length > 0 && !allSelected;

    const toggleSelectAll = () => {
      const newValues = allSelected
        ? []
        : maxSelections
          ? selectableValues.slice(0, maxSelections)
          : selectableValues;
      if (!isControlled) {
        setInternalValue(newValues);
      }
      onValueChange?.(newValues);
    };

    // Close dropdown when clicking outside
    React.useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          containerRef.current &&
          !containerRef.current.contains(event.target as Node)
        ) {
          setIsOpen(false);
          setSearchQuery("");
        }
      };

      document.addEventListener("mousedown", handleClickOutside);
      return () =>
        document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // Handle keyboard navigation
    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Escape" && closeOnEscape) {
        setIsOpen(false);
        setSearchQuery("");
      } else if (e.key === "Enter" || e.key === " ") {
        if (!isOpen) {
          e.preventDefault();
          setIsOpen(true);
        }
      }
    };

    return (
      <div
        ref={containerRef}
        className={cn("flex flex-col gap-1", wrapperClassName)}
      >
        {/* Label */}
        {label && (
          <label
            htmlFor={selectId}
            className={cn(
              "text-xs font-normal text-semantic-text-muted",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Trigger + helper/error + listbox share one positioning context so the
            menu opens directly under the field (and under helper text when present). */}
        <div className="relative w-full min-w-0 flex flex-col gap-1">
          {/* Trigger */}
          <button
            ref={ref}
            id={selectId}
            type="button"
            role="combobox"
            aria-expanded={isOpen}
            aria-haspopup="listbox"
            aria-controls={listboxId}
            aria-invalid={!!error}
            aria-describedby={ariaDescribedBy}
            disabled={disabled || loading}
            onClick={() => !disabled && !loading && setIsOpen(!isOpen)}
            onKeyDown={handleKeyDown}
            className={cn(
              multiSelectTriggerVariants({ state: derivedState }),
              "text-left gap-2",
              triggerClassName
            )}
          >
          <div className="flex-1 flex flex-wrap gap-1">
            {selectedValues.length === 0 ? (
              <span className="text-semantic-text-placeholder">
                {placeholder}
              </span>
            ) : summaryLabel ? (
              <TooltipProvider delayDuration={200}>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span>{summaryLabel(selectedValues.length)}</span>
                  </TooltipTrigger>
                  <TooltipContent>
                    <div className="flex flex-col gap-0.5">
                      {selectedLabels.map((label, index) => (
                        <span key={selectedValues[index]}>{label}</span>
                      ))}
                    </div>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            ) : (
              selectedLabels.map((label, index) => (
                <span
                  key={selectedValues[index]}
                  className="inline-flex items-center gap-1 bg-semantic-bg-ui text-semantic-text-primary text-xs px-2 py-0.5 rounded"
                >
                  {label}
                  <span
                    role="button"
                    tabIndex={0}
                    onClick={(e) => removeValue(selectedValues[index], e)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        removeValue(
                          selectedValues[index],
                          e as unknown as React.MouseEvent
                        );
                      }
                    }}
                    className="cursor-pointer hover:text-semantic-error-primary focus:outline-none"
                    aria-label={`Remove ${label}`}
                  >
                    <X className="size-3" />
                  </span>
                </span>
              ))
            )}
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {showClearAll && selectedValues.length > 0 && (
              <span
                role="button"
                tabIndex={0}
                onClick={clearAll}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    clearAll(e as unknown as React.MouseEvent);
                  }
                }}
                className="p-0.5 cursor-pointer hover:text-semantic-error-primary focus:outline-none"
                aria-label="Clear all"
              >
                <X className="size-4 text-semantic-text-muted" />
              </span>
            )}
            {showSeparatorBeforeChevron && (
              <div
                className="w-px h-5 self-center border-l border-solid border-semantic-border-layout shrink-0"
                aria-hidden
              />
            )}
            {loading ? (
              <Loader2 className="size-4 animate-spin text-semantic-text-muted" />
            ) : (
              <ChevronDown
                className={cn(
                  "size-4 text-semantic-text-muted transition-transform shrink-0",
                  isOpen && "rotate-180"
                )}
              />
            )}
          </div>
        </button>

          {/* Helper / error sits between trigger and dropdown (normal flow), matching Figma */}
          {(error || helperText) && (
            <div className="flex justify-between items-start gap-2">
              {error ? (
                <div
                  id={errorId}
                  role="alert"
                  className="flex items-center gap-1.5 min-w-0"
                >
                  <CircleAlert
                    className="size-3.5 shrink-0 text-semantic-error-primary"
                    aria-hidden
                  />
                  <span className="text-xs text-semantic-error-primary">
                    {error}
                  </span>
                </div>
              ) : helperText ? (
                <span
                  id={helperId}
                  className="text-xs text-semantic-text-muted"
                >
                  {helperText}
                </span>
              ) : null}
            </div>
          )}

          {/* Dropdown */}
          {isOpen && (
            <TooltipProvider delayDuration={200}>
              <div
                id={listboxId}
                className={cn(
                  "absolute left-0 right-0 z-[100] mt-1 w-full rounded bg-semantic-bg-primary border border-solid border-semantic-border-layout shadow-md",
                  "top-full"
                )}
                role="listbox"
                aria-multiselectable="true"
              >
              {/* Search input */}
              {searchable && (
                <div className="p-2 border-b border-solid border-semantic-border-layout">
                  <input
                    type="text"
                    placeholder={searchPlaceholder}
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full h-8 px-3 text-sm border border-solid border-semantic-border-input rounded bg-semantic-bg-primary placeholder:text-semantic-text-placeholder focus:outline-none focus:border-semantic-border-input-focus/50"
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>
              )}

              {/* Select all */}
              {selectAllLabel && (
                <div
                  role="option"
                  aria-selected={allSelected}
                  tabIndex={0}
                  onClick={toggleSelectAll}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      toggleSelectAll();
                    }
                  }}
                  className="flex w-full cursor-pointer select-none items-center gap-2 border-b border-solid border-semantic-border-layout px-3 py-2 text-sm text-semantic-text-primary outline-none hover:bg-semantic-bg-ui"
                >
                  <Checkbox
                    checked={allSelected ? true : someSelected ? "indeterminate" : false}
                    size="sm"
                    className="pointer-events-none shrink-0"
                    aria-hidden
                    tabIndex={-1}
                  />
                  <span className="min-w-0 flex-1 truncate text-left">{selectAllLabel}</span>
                </div>
              )}

              {/* Options */}
              <div className="max-h-60 overflow-auto p-1">
                {filteredOptions.length === 0 ? (
                  <div className="py-6 text-center text-sm text-semantic-text-muted">
                    No results found
                  </div>
                ) : (
                  displayItems.map((item, itemIndex) => {
                    if (item.type === "divider") {
                      return (
                        <div
                          key={`divider-${itemIndex}`}
                          role="separator"
                          className="my-1 h-px bg-semantic-border-layout"
                        />
                      );
                    }
                    if (item.type === "header") {
                      return (
                        <div
                          key={`header-${item.label}-${itemIndex}`}
                          className="px-3 pt-2 pb-1 text-xs font-semibold uppercase tracking-wide text-semantic-text-muted"
                        >
                          {item.label}
                        </div>
                      );
                    }

                    const option = item.option;
                    const isSelected = selectedValues.includes(option.value);
                    const isMaxedOut =
                      !isSelected &&
                      maxSelections !== undefined &&
                      maxSelections > 0 &&
                      selectedValues.length >= maxSelections;
                    const isDisabled =
                      Boolean(option.disabled) || isMaxedOut;
                    const secondaryLine = option.secondaryText ?? option.caption;

                    const rowClass = cn(
                      "relative flex w-full min-w-0 cursor-pointer select-none items-center rounded-sm text-left text-semantic-text-primary outline-none",
                      optionVariant === "detailed"
                        ? "gap-2 px-2 py-2 text-sm"
                        : "py-2 pl-4 pr-8 text-base",
                      !isSelected &&
                        "hover:bg-semantic-bg-ui focus:bg-semantic-bg-ui",
                      isDisabled && "opacity-50 cursor-not-allowed",
                      option.isDeleted && "line-through opacity-70"
                    );

                    const simpleRow = (
                      <button
                        type="button"
                        role="option"
                        aria-selected={isSelected}
                        disabled={isDisabled}
                        onClick={() =>
                          !isDisabled && toggleOption(option.value)
                        }
                        className={rowClass}
                      >
                        <span className="absolute right-2 flex size-4 items-center justify-center">
                          {isSelected && (
                            <Check className="size-4 text-semantic-brand" />
                          )}
                        </span>
                        <span className="min-w-0 flex-1 whitespace-normal break-words text-left">
                          {option.label}
                        </span>
                      </button>
                    );

                    const detailedRow = (
                      <div
                        role="option"
                        tabIndex={isDisabled ? -1 : 0}
                        aria-selected={isSelected}
                        aria-disabled={isDisabled}
                        data-disabled={isDisabled ? "" : undefined}
                        onClick={() =>
                          !isDisabled && toggleOption(option.value)
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault();
                            if (!isDisabled) toggleOption(option.value);
                          }
                        }}
                        className={rowClass}
                      >
                        <Checkbox
                          checked={isSelected}
                          disabled={isDisabled}
                          size="sm"
                          className="pointer-events-none shrink-0"
                          aria-hidden
                          tabIndex={-1}
                        />
                        <span className="min-w-0 flex-1 truncate text-left">
                          {option.label}
                        </span>
                        {secondaryLine ? (
                          <span className="shrink-0 max-w-[55%] truncate text-right text-xs text-semantic-text-muted">
                            {secondaryLine}
                          </span>
                        ) : null}
                      </div>
                    );

                    const overlayCopy =
                      option.disabledTooltip ?? option.overlayMsg;

                    const withDisabledTooltip = (node: React.ReactElement) =>
                      isDisabled && overlayCopy ? (
                        <Tooltip key={option.value}>
                          <TooltipTrigger asChild>
                            <span className="block w-full cursor-default">
                              {node}
                            </span>
                          </TooltipTrigger>
                          <TooltipContent
                            side="top"
                            className="max-w-xs bg-semantic-primary text-semantic-text-inverted border-semantic-primary"
                          >
                            {overlayCopy}
                          </TooltipContent>
                        </Tooltip>
                      ) : (
                        <React.Fragment key={option.value}>
                          {node}
                        </React.Fragment>
                      );

                    if (optionVariant === "detailed") {
                      return withDisabledTooltip(detailedRow);
                    }

                    return withDisabledTooltip(simpleRow);
                  })
                )}
              </div>

              {/* Footer with count */}
              {maxSelections && showSelectionFooter ? (
                <div className="p-2 border-t border-solid border-semantic-border-layout text-xs text-semantic-text-muted">
                  {selectedValues.length} / {maxSelections} selected
                </div>
              ) : null}
              </div>
            </TooltipProvider>
          )}
        </div>

        {/* Hidden input for form submission */}
        {name &&
          selectedValues.map((v) => (
            <input key={v} type="hidden" name={name} value={v} />
          ))}
      </div>
    );
  }
);
