/**
 * Table size variants for row height.
 */
const tableVariants = cva("w-full caption-bottom text-sm", {
  variants: {
    size: {
      sm: "[&_td]:py-2 [&_th]:py-2",
      md: "[&_td]:py-3 [&_th]:py-3",
