import * as React from "react";
import * as TooltipPrimitive from "@radix-ui/react-tooltip";

import { cn } from "@/lib/utils";

const TooltipProvider = TooltipPrimitive.Provider;

/** True when the primary input cannot hover (touch / most phones & tablets). Desktop hover stays false. */
function usePrefersTapTooltipInteraction() {
  const [tapMode, setTapMode] = React.useState(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return false;
    }
    return window.matchMedia("(hover: none)").matches;
  });

  React.useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return;
    }
    const mq = window.matchMedia("(hover: none)");
    const sync = () => setTapMode(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  return tapMode;
}

type TooltipFieldContextValue = {
  tapMode: boolean;
  open: boolean;
  setOpen: (next: boolean | ((prev: boolean) => boolean)) => void;
  isControlled: boolean;
  /** True after pointerdown on touch; Radix may fire onOpenChange(true) from focus before click — ignore that open. */
  suppressFocusOpenRef: React.MutableRefObject<boolean>;
};

const TooltipFieldContext = React.createContext<TooltipFieldContextValue | null>(null);

function useTooltipFieldContext() {
  const ctx = React.useContext(TooltipFieldContext);
  if (!ctx) {
    throw new Error("TooltipTrigger must be used within Tooltip");
  }
  return ctx;
}

const Tooltip = (props: React.ComponentProps<typeof TooltipPrimitive.Root>) => {
  const { open: openProp, defaultOpen, onOpenChange: onOpenChangeProp, delayDuration: delayDurationProp } = props;
  const tapMode = usePrefersTapTooltipInteraction();
  const isControlled = openProp !== undefined;
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(() => defaultOpen ?? false);

  const suppressFocusOpenRef = React.useRef(false);

  const handleOpenChange = React.useCallback(
    (next: boolean) => {
      if (!isControlled) {
        if (tapMode && next === true && suppressFocusOpenRef.current) {
          return;
        }
        setUncontrolledOpen(next);
      }
      onOpenChangeProp?.(next);
    },
    [isControlled, onOpenChangeProp, tapMode],
  );

  const openSnapshot = isControlled ? openProp! : uncontrolledOpen;

  const setOpen = React.useCallback(
    (next: boolean | ((prev: boolean) => boolean)) => {
      if (isControlled) {
        const value = typeof next === "function" ? next(openProp!) : next;
        onOpenChangeProp?.(value);
      } else {
        setUncontrolledOpen(next);
      }
    },
    [isControlled, openProp, onOpenChangeProp],
  );

  const rootProps: React.ComponentProps<typeof TooltipPrimitive.Root> = (() => {
    if (isControlled) {
      return props;
    }
    if (tapMode) {
      return {
        ...props,
        defaultOpen: undefined,
        open: uncontrolledOpen,
        onOpenChange: handleOpenChange,
        delayDuration: delayDurationProp ?? 0,
      };
    }
    return {
      ...props,
      onOpenChange: handleOpenChange,
    };
  })();

  const contextValue: TooltipFieldContextValue = {
    tapMode,
    open: openSnapshot,
    setOpen,
    isControlled,
    suppressFocusOpenRef,
  };

  return (
    <TooltipFieldContext.Provider value={contextValue}>
      <TooltipPrimitive.Root {...rootProps} />
    </TooltipFieldContext.Provider>
  );
};
Tooltip.displayName = TooltipPrimitive.Root.displayName;

const TooltipTrigger = React.forwardRef<
  React.ElementRef<typeof TooltipPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Trigger>
>(({ onPointerDown, onClick, className, ...props }, ref) => {
  const { tapMode, open, setOpen, isControlled, suppressFocusOpenRef } = useTooltipFieldContext();

  const onPointerDownForTap = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (tapMode) {
        suppressFocusOpenRef.current = true;
      }
      if (tapMode && open) {
        e.preventDefault();
      }
    },
    [tapMode, open, suppressFocusOpenRef],
  );

  const onClickForTap = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      if (!tapMode) {
        return;
      }
      e.preventDefault();
      if (isControlled) {
        setOpen(!open);
      } else {
        setOpen((o) => !o);
      }
      suppressFocusOpenRef.current = false;
    },
    [tapMode, isControlled, open, setOpen, suppressFocusOpenRef],
  );

  return (
    <TooltipPrimitive.Trigger
      ref={ref}
      {...props}
      className={cn("cursor-pointer", className)}
      onPointerDown={(e) => {
        onPointerDown?.(e);
        if (!e.defaultPrevented) {
          onPointerDownForTap(e);
        }
      }}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) {
          onClickForTap(e);
        }
      }}
    />
  );
});
TooltipTrigger.displayName = TooltipPrimitive.Trigger.displayName;

const TooltipContent = React.forwardRef(({ className, sideOffset = 4, ...props }: React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Content>, ref: React.Ref<React.ElementRef<typeof TooltipPrimitive.Content>>) => (
  <TooltipPrimitive.Portal>
    <TooltipPrimitive.Content
      ref={ref}
      sideOffset={sideOffset}
      className={cn(
        "z-[9999] pointer-events-none data-[state=delayed-open]:pointer-events-auto data-[state=instant-open]:pointer-events-auto overflow-hidden rounded-md bg-semantic-primary px-3 py-1.5 text-xs text-semantic-text-inverted shadow-md animate-in fade-in-0 zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 max-w-xs whitespace-normal",
        className
      )}
      {...props}
    />
  </TooltipPrimitive.Portal>
));
TooltipContent.displayName = TooltipPrimitive.Content.displayName;

const TooltipArrow = React.forwardRef(({ className, ...props }: React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Arrow>, ref: React.Ref<React.ElementRef<typeof TooltipPrimitive.Arrow>>) => (
  <TooltipPrimitive.Arrow
    ref={ref}
    className={cn("fill-semantic-primary", className)}
    {...props}
  />
));
TooltipArrow.displayName = TooltipPrimitive.Arrow.displayName;

export {
  Tooltip,
  TooltipTrigger,
  TooltipContent,
  TooltipArrow,
  TooltipProvider,
};

import * as React from "react";

import { cn } from "@/lib/utils";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
  DialogTrigger,
} from "./dialog";
import { Button } from "./button";
import { Input } from "./input";

/**
 * Props for the DeleteConfirmationModal component
 */
export interface DeleteConfirmationModalProps {
  /** Controls modal visibility (controlled mode) */
  open?: boolean;
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** The name of the item being deleted (shown in title) */
  itemName?: string;
  /** Custom title (overrides default) */
  title?: React.ReactNode;
  /** Additional description text */
  description?: React.ReactNode;
  /** Text user must type to confirm (default: "DELETE") */
  confirmText?: string;
  /** Called when user confirms deletion */
  onConfirm?: () => void;
  /** Called when user cancels */
  onCancel?: () => void;
  /** Loading state for delete button */
  loading?: boolean;
  /** Text for delete button (default: "Delete") */
  deleteButtonText?: string;
  /** Text for cancel button (default: "Cancel") */
  cancelButtonText?: string;
  /** Trigger element for uncontrolled usage */
  trigger?: React.ReactNode;
  /** Additional className for the dialog content */
  className?: string;
}

/**
 * A confirmation modal that requires the user to type a specific text to confirm deletion.
 *
 * @example
 * ```tsx
 * // Controlled usage
 * <DeleteConfirmationModal
 *   open={isOpen}
 *   onOpenChange={setIsOpen}
 *   itemName="webhook"
 *   onConfirm={handleDelete}
 * />
 *
 * // Uncontrolled with trigger
 * <DeleteConfirmationModal
 *   trigger={<Button variant="destructive">Delete</Button>}
 *   itemName="user"
 *   onConfirm={handleDelete}
 * />
 * ```
 */
const DeleteConfirmationModal = React.forwardRef(
  (
    {
      open,
      onOpenChange,
      itemName = "item",
      title,
      description,
      confirmText = "DELETE",
      onConfirm,
      onCancel,
      loading = false,
      deleteButtonText = "Delete",
      cancelButtonText = "Cancel",
      trigger,
      className,
    }: DeleteConfirmationModalProps,
    ref: React.Ref<HTMLDivElement>
  ) => {
    const [inputValue, setInputValue] = React.useState("");
    const isConfirmEnabled = inputValue === confirmText;

    // Reset input when modal closes
    React.useEffect(() => {
      if (!open) {
        setInputValue("");
      }
    }, [open]);

    const handleConfirm = () => {
      if (isConfirmEnabled) {
        onConfirm?.();
      }
    };

    const handleCancel = () => {
      onCancel?.();
      onOpenChange?.(false);
    };

    const handleOpenChange = (newOpen: boolean) => {
      if (!newOpen) {
        setInputValue("");
      }
      onOpenChange?.(newOpen);
    };

    const defaultTitle = `Are you sure you want to delete this ${itemName}?`;

    return (
      <Dialog open={open} onOpenChange={handleOpenChange}>
        {trigger && <DialogTrigger asChild>{trigger}</DialogTrigger>}
        <DialogContent ref={ref} size="sm" className={cn(className)}>
          <DialogHeader>
            <DialogTitle>{title || defaultTitle}</DialogTitle>
            <DialogDescription className={description ? undefined : "sr-only"}>
              {description ||
                "Delete confirmation dialog - this action cannot be undone"}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-2 py-4">
            <label
              htmlFor="delete-confirmation-input"
              className="text-sm text-muted-foreground"
            >
              Enter "{confirmText}" in uppercase to confirm
            </label>
            <Input
              id="delete-confirmation-input"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder={confirmText}
              autoComplete="off"
              autoFocus
            />
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button variant="outline" onClick={handleCancel} disabled={loading}>
              {cancelButtonText}
            </Button>
            <Button
              variant="destructive"
              onClick={handleConfirm}
              disabled={!isConfirmEnabled || loading}
              loading={loading}
            >
              {deleteButtonText}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }
);
DeleteConfirmationModal.displayName = "DeleteConfirmationModal";

export { DeleteConfirmationModal };

import * as React from "react";

import { cn } from "@/lib/utils";
